text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي لتقنية المعلومات",
  "planted": [
    {
      "slot": "p1",
      "text": "يُعد استخدامك للمنصة أو استمرارك في تصفح خدماتنا بمثابة إقرار صريح وموافقة نهائية لا تقبل التراجع على جميع أوجه جمع ومعالجة بياناتك الشخصية وتغيير أراضيها، ولا يحق للمستخدم سحب هذه الموافقة أو تقييدها بأي شكل من الأشكال طالما كان الحساب نشطاً في النظام."
    },
    {
      "slot": "p2",
      "text": "تلتزم الشركة بإبلاغ الجهة التنظيمية المختصة خلال اثنتين وسبعين ساعة فور علمها بأي اختراق أو تلف أو وصول غير قانوني للبيانات الشخصية، كما تتعهد بإشعار المستخدم المتضرر دون إبطاء إذا كان من المرجح أن يؤدي هذا الحادث إلى المساس بحقوقه أو بياناته الشخصية."
    },
    {
      "slot": "p3",
      "text": "يحق لكل مستخدم الاطلاع على الأسباب النظامية والأغراض المحددة لجمع بياناته الشخصية، وطلب الوصول إليها، أو تصحيحها، أو استكمالها، أو تحديثها، بالإضافة إلى طلب إتلاف البيانات التي انتفت الحاجة إليها."
    },
    {
      "slot": "p4",
      "text": "تقوم الشركة بالتعامل مع البيانات الشخصية والاحتفاظ بها للمدة اللازمة لتحقيق أهداف تقديم الخدمة، وتتم عملية إتلافها أو إخفاء هويتها وفقاً للجدول الزمني الداخلي المعتمد للعمليات التشغيلية."
    }
  ],
  "neutral": [
    "تعريفات: يقصد بالخدمة منصة الأفق الرقمي، ويقصد بالعميل كل شخص طبيعي أو اعتباري يستفيد من الخدمات المقدمة.",
    "الرسوم والمدفوعات: تخضع كافة الخدمات لرسوم مالية محددة في صفحة الأسعار، ويتم سدادها مقدماً عبر وسائل الدفع المعتمدة لدى الشركة.",
    "المدة والإنهاء: تبدأ هذه الاتفاقية فور إتمام التسجيل وتستمر حتى قيام أحد الطرفين بإنهاء الحساب وفقاً للإجراءات المقررة.",
    "الملكية الفكرية: جميع حقوق الملكية الفكرية والعلامات التجارية والمحتوى المعروض على المنصة هي ملك حصري للشركة ولا يجوز استخدامها دون إذن خطي.",
    "التسليم: يتم توفير الوصول للخدمات الرقمية فور اكتمال عملية الدفع وتأكيد الحساب إلكترونياً.",
    "حدود المسؤولية: لا تتحمل الشركة أي أضرار غير مباشرة أو تبعية قدל تنتج عن استخدام أو عدم القدرة على استخدام الخدمات.",
    "الإشعارات: تُوجه كافة المراسلات الرسمية والإشعارات عبر البريد الإلكتروني المسجل للعميل أو من خلال لوحة التحكم الخاصة بحسابه.",
    "القانون الواجب التطبيق: تخضع هذه الشروط وتفسر وفقاً لأنظمة وقوانين المملكة العربية السعودية وتختص المحاكم وحدها بالنظر في أي نزاع."
  ]
}
